import{_ as a,c as t,o,aj as s}from"./chunks/framework.Id7s26SP.js";const m=JSON.parse('{"title":"Interface: DocumentSnapshotsAPI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/DocumentSnapshotsAPI.md","filePath":"reference/js-bao-wss-client/api/interfaces/DocumentSnapshotsAPI.md"}'),r={name:"reference/js-bao-wss-client/api/interfaces/DocumentSnapshotsAPI.md"};function n(d,e,i,c,h,l){return o(),t("div",null,[...e[0]||(e[0]=[s('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / DocumentSnapshotsAPI</p><h1 id="interface-documentsnapshotsapi" tabindex="-1">Interface: DocumentSnapshotsAPI <a class="header-anchor" href="#interface-documentsnapshotsapi" aria-label="Permalink to “Interface: DocumentSnapshotsAPI”">​</a></h1><p>Snapshot builds of a large document. Accessed as <code>client.documents.snapshots</code>.</p><p>A large document&#39;s records live in a base snapshot plus the overlays sealed since it, and the server rebuilds that base as the document grows. These reads are the window onto what it built and whether it verified.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="build" tabindex="-1">build() <a class="header-anchor" href="#build" aria-label="Permalink to “build()”">​</a></h3><blockquote><p><strong>build</strong>(<code>documentId</code>): <code>Promise</code>&lt;<a href="./../type-aliases/DocumentSnapshotRequest.html"><code>DocumentSnapshotRequest</code></a>&gt;</p></blockquote><p>Snapshot the document now, instead of waiting for the size or age trigger.</p><p>Seals the epoch the document is writing to and starts the base build that seal arms; the answer names the epoch that was sealed and the build, so <a href="#get">DocumentSnapshotsAPI.get</a> can follow it. An epoch that carries nothing is not sealed at all and the answer says so.</p><p>Requires the permission a bulk load requires — a document grant at <code>read-write</code> or above, or an app admin — not merely read access.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid" tabindex="-1">documentId <a class="header-anchor" href="#documentid" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><p>The large document to snapshot</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./../type-aliases/DocumentSnapshotRequest.html"><code>DocumentSnapshotRequest</code></a>&gt;</p><hr><h3 id="get" tabindex="-1">get() <a class="header-anchor" href="#get" aria-label="Permalink to “get()”">​</a></h3><blockquote><p><strong>get</strong>(<code>documentId</code>, <code>buildId</code>): <code>Promise</code>&lt;<a href="./DocumentSnapshotBuild.html"><code>DocumentSnapshotBuild</code></a>&gt;</p></blockquote><p>One build, with its verification result and its stage timings.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-1" tabindex="-1">documentId <a class="header-anchor" href="#documentid-1" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><p>The document the build belongs to</p><h5 id="buildid" tabindex="-1">buildId <a class="header-anchor" href="#buildid" aria-label="Permalink to “buildId”">​</a></h5><p><code>string</code></p><p>The build to read</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./DocumentSnapshotBuild.html"><code>DocumentSnapshotBuild</code></a>&gt;</p><hr><h3 id="list" tabindex="-1">list() <a class="header-anchor" href="#list" aria-label="Permalink to “list()”">​</a></h3><blockquote><p><strong>list</strong>(<code>documentId</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./DocumentSnapshotPage.html"><code>DocumentSnapshotPage</code></a>&gt;</p></blockquote><p>A document&#39;s snapshot builds, newest first.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="documentid-2" tabindex="-1">documentId <a class="header-anchor" href="#documentid-2" aria-label="Permalink to “documentId”">​</a></h5><p><code>string</code></p><p>The document whose builds to list</p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p>Page size and cursor</p><h6 id="cursor" tabindex="-1">cursor? <a class="header-anchor" href="#cursor" aria-label="Permalink to “cursor?”">​</a></h6><p><code>string</code></p><h6 id="limit" tabindex="-1">limit? <a class="header-anchor" href="#limit" aria-label="Permalink to “limit?”">​</a></h6><p><code>number</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./DocumentSnapshotPage.html"><code>DocumentSnapshotPage</code></a>&gt;</p>',47)])])}const u=a(r,[["render",n]]);export{m as __pageData,u as default};
